// Parse Message Code Node — extracts phone, text, trace_id from WhatsApp webhook payload
// TODO: Inject from n8n-workflows/code-nodes/parse-message.js if created
const crypto = require('crypto');
const msg = $input.first().json;
const body = msg.body || msg.entry?.[0]?.changes?.[0]?.value?.messages?.[0] || {};
const text = body.text?.body || body.body || '';
const phone = body.from || msg.from || '';
const trace_id = crypto.randomUUID();

return [{ json: { phone, message: { text, original_text: text }, trace_id, raw: msg } }];

// Status / Info Code Node — ticket lookup + scheme info
// TODO: Implement per task 7.3
const text = $json.message?.text || '';
return [{ json: { ...$json, reply: `Status check for: ${text}` } }];

// Welcome Code Node — greeting response
const reply = '🙏 নমস্কার! আমি সহায়ক (Sahayak)।

I can help you with:
1️⃣ File a complaint (অভিযোগ)
2️⃣ Request blood (রক্তের অনুরোধ)
3️⃣ Register as donor (দাতা নিবন্ধন)
4️⃣ Check complaint status
5️⃣ Scheme information

Please type your need or say Hi!';
return [{ json: { ...$json, reply } }];

// Fallback Code Node — default branch when Switch has no match
const reply = 'I\'m sorry, I didn\'t understand that. Please try again or type "Hi" to see available options.';
return [{ json: { ...$json, reply } }];

// Fire Observability — async fire-and-forget call to JS-01v2-Observability sub-workflow
// Builds the observability payload from $json and fires an HTTP POST.
// Uses a short timeout and catches errors silently so observability never blocks the reply path.

const baseUrl = $env.N8N_BASE_URL || $env.API_BASE_URL || 'https://wb-grievance-portal.vercel.app';
const webhookPath = `${baseUrl}/webhook/js01v2-observability`;

// Build the routing_decision payload from the current execution context
const payload = {
  kind: 'routing_decision',
  payload: {
    session_id: $json.phone || null,
    message_text: ($json.message?.text || '').substring(0, 200),
    last_intent_before: $json.prev_last_intent || $json.session?.last_intent || null,
    agent_dispatched: $json.agent || null,
    reason: $json.reason || '',
    trace_id: $json.trace_id || null
  }
};

// Fire-and-forget: send the POST but do NOT await the response.
// Errors are caught silently — observability must never block the reply path.
try {
  $http.request({
    method: 'POST',
    url: webhookPath,
    body: payload,
    json: true,
    timeout: 3000,
    headers: { 'Content-Type': 'application/json' }
  }).catch(() => { /* silent — observability failure is non-fatal */ });
} catch (e) {
  // Silent catch — observability must never throw
}

// Return the original $json unchanged so the workflow can end cleanly
return [{ json: $json }];
